"use strict";(self.webpackChunkfrontend=self.webpackChunkfrontend||[]).push([[149],{149:e=>{e.exports=JSON.parse('{"lesson_id":4,"lesson_title":"Authentication & Authorization \u2014 JWT + Sessions","questions":[{"id":1,"type":"debug","question":"Why does this middleware accept any token and allow access without checking expiry or signature?","code":"const jwt = require(\'jsonwebtoken\');\\nfunction auth(req, res, next) {\\n  const token = req.headers.authorization?.split(\' \')[1];\\n  if (!token) return res.status(401).send(\'No token\');\\n  const payload = jwt.decode(token);\\n  req.user = payload;\\n  next();\\n}","options":["jwt.decode() does not verify signature or expiry \u2014 use jwt.verify() with the secret","Authorization header must be named X-Auth-Token","decode() automatically refreshes tokens which is insecure","You must parse token from req.query not headers"],"correctIndex":0,"difficulty":"medium","topic":"jwt-verification"},{"id":2,"type":"debug","question":"What is the main security issue with storing JWT access tokens in localStorage?","code":"// client-side\\nlocalStorage.setItem(\'accessToken\', token);\\n// send with fetch\\nfetch(\'/api/protected\', { headers: { Authorization: `Bearer ${localStorage.getItem(\'accessToken\')}` } });","options":["localStorage is accessible to JavaScript and vulnerable to XSS; use httpOnly cookies for sensitive tokens","localStorage automatically encrypts data which developers often forget","Browsers prevent Authorization headers when values are in localStorage","localStorage will expire tokens automatically causing silent failures"],"correctIndex":0,"difficulty":"easy","topic":"token-storage"},{"id":3,"type":"mcq","question":"Which header and format is the conventional way to send a bearer JWT to the server?","options":["Authorization: Bearer <token>","X-Auth-Token: token=<token>","Cookie: token=<token>","Auth: JWT <token>"],"correctIndex":0,"difficulty":"easy","topic":"jwt-transport"},{"id":4,"type":"debug","question":"Why will this Express session cookie not be sent in production over HTTPS?","code":"app.use(session({ secret: \'s\', resave: false, saveUninitialized: false, cookie: { secure: false } }));","options":["cookie.secure is false \u2014 in production should be true so it is only sent over HTTPS","secret must be 64 characters long","Express sessions cannot be used with HTTPS","cookie.maxAge is required for sending cookies"],"correctIndex":0,"difficulty":"medium","topic":"express-session"},{"id":5,"type":"debug","question":"What is wrong with this token refresh design?","code":"// on login:\\nres.cookie(\'refresh\', refreshToken);\\nres.json({ accessToken });\\n// refresh endpoint:\\napp.post(\'/refresh\', (req, res) => {\\n  const r = req.cookies.refresh;\\n  const payload = jwt.verify(r, REFRESH_SECRET);\\n  const accessToken = jwt.sign({ uid: payload.uid }, ACCESS_SECRET, { expiresIn: \'15m\' });\\n  res.json({ accessToken });\\n});","options":["Refresh cookie is not httpOnly/secure by default \u2014 should be set as httpOnly and sent only over HTTPS","Refresh tokens should live in localStorage, not cookies","Access tokens should be issued with no expiry when refresh tokens exist","Refresh token should be verified with the same secret as access tokens"],"correctIndex":0,"difficulty":"medium","topic":"refresh-token"},{"id":6,"type":"mcq","question":"Which of the following is a proper reason to prefer server-side sessions over stateless JWTs?","options":["Ability to revoke sessions immediately on logout or admin action","JWTs are always larger in size than cookies","Sessions do not require any server storage","JWTs cannot include custom claims"],"correctIndex":0,"difficulty":"medium","topic":"sessions-vs-jwt"},{"id":7,"type":"debug","question":"Why is this authorization middleware insufficient for protected routes?","code":"function requireRole(role) {\\n  return (req, res, next) => {\\n    if (!req.user) return res.status(401).send(\'Unauthorized\');\\n    if (req.user.role === role) return next();\\n    return res.status(403).send(\'Forbidden\');\\n  }\\n}\\n// route: app.get(\'/admin\', requireRole(\'admin\'), handler)","options":["It only allows the exact role; for \'admin\' you may need role hierarchy or multiple roles \u2014 but this is often acceptable; main issue: no check that req.user was verified (token verification) earlier","Middleware must mutate req.session to add roles","Role strings must be stored in uppercase in database","You should only check role in controllers, not middleware"],"correctIndex":0,"difficulty":"medium","topic":"authorization"},{"id":8,"type":"debug","question":"Why might this logout endpoint fail to prevent the access token from being reused?","code":"app.post(\'/logout\', (req, res) => {\\n  res.clearCookie(\'refresh\');\\n  res.sendStatus(200);\\n}); // client still has access token in memory/localStorage","options":["Clearing the refresh cookie doesn\'t invalidate already-issued access tokens; access tokens remain valid until expiry unless tracked server-side","res.clearCookie does not remove cookies from browser","You must delete the user record to fully logout","Logout endpoints must call jwt.revoke() which exists in std lib"],"correctIndex":0,"difficulty":"easy","topic":"logout"},{"id":9,"type":"mcq","question":"Which cookie flags should you set for authentication cookies in production?","options":["httpOnly, secure, sameSite=strict","autoRefresh=true","expires=never","Same as localStorage settings"],"correctIndex":0,"difficulty":"easy","topic":"cookie-security"},{"id":10,"type":"debug","question":"What is the bug here when creating a JWT for a user?","code":"const token = jwt.sign({ uid: user.uid }, process.env.JWT_SECRET || \'dev\');\\n// later on production the secret is changed so previously issued tokens are invalid","options":["Using an environment fallback secret like \'dev\' can leak predictable secrets; also rotating the secret will invalidate tokens \u2014 use stable secret management or token rotation strategy","JWT secrets must be stored in a database, not env vars","jwt.sign will automatically rotate secrets unless told not to","Tokens created with jwt.sign are always valid regardless of secret"],"correctIndex":0,"difficulty":"medium","topic":"jwt-secret"}]}')}}]);